const bookIcons = [
  BookIconRed,
  BookIconBlue,
  BookIconGreen,
  BookIconGold,
  BookIconWord,
];

function BookIcon({ index, uid }: { index: number; uid: string }) {
  const Icon = bookIcons[index % bookIcons.length];
  return <Icon uid={uid} />;
}

